import React, { useState } from "react";
import DepartmentCard from "../../components/DepartmentCard";
import ContentItem from "../../components/ContentItem";
import departmentsData from "../../data/departments.json";

const Learn = () => {
  // ----------------------------
  // State: Selected department
  // ----------------------------
  const [selectedDept, setSelectedDept] = useState(null);

  // ----------------------------
  // State: Age group filter ("children" or "teens")
  // ----------------------------
  const [ageGroup, setAgeGroup] = useState("children");

  // ----------------------------
  // Handle age group toggle
  // ----------------------------
  const handleAgeGroup = (group) => setAgeGroup(group);

  // ----------------------------
  // Handle department selection
  // ----------------------------
  const handleSelectDept = (dept) => setSelectedDept(dept);

  return (
    <main className="p-6 min-h-screen bg-slate-100">
      {/* Page title */}
      <h2 className="text-3xl font-bold text-center mb-6">
        Learn About the Hospital 🏥
      </h2>

      {/* Age group toggle */}
      <div className="flex justify-center gap-4 mb-8">
        {["children", "teens"].map((group) => (
          <button
            key={group}
            onClick={() => handleAgeGroup(group)}
            className={`px-5 py-2 rounded-xl font-semibold transition-colors duration-200 ${
              ageGroup === group
                ? "bg-purple-500 text-white shadow-lg"
                : "bg-gray-200 text-gray-700 hover:bg-gray-300"
            }`}
          >
            {group === "children" ? "Children (4–10)" : "Teens (11–18)"}
          </button>
        ))}
      </div>

      {/* Departments menu */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6 mb-8">
        {departmentsData.map((dept) => (
          <DepartmentCard
            key={dept.id}
            name={dept.name}
            icon={dept.icon}
            onClick={() => handleSelectDept(dept)}
          />
        ))}
      </div>

      {/* Selected department content */}
      {selectedDept && (
        <div className="mb-10">
          <h3 className="text-2xl font-bold mb-4 text-purple-700">
            {selectedDept.name}
          </h3>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {selectedDept.content[ageGroup].map((item, idx) => (
              <ContentItem key={idx} item={item} />
            ))}
          </div>

          {/* If this is the "Try Being the Doctor" department, render interactive area */}
          {selectedDept.name === "Try Being the Doctor" && (
            <div className="mt-8 bg-white p-6 rounded-2xl shadow-lg text-center">
              <h4 className="font-bold text-xl mb-4">
                🩺 Try Being the Doctor!
              </h4>
              <p className="mb-4">
                Pretend to check a patient, measure vitals, and diagnose!
              </p>
              <div className="flex justify-center gap-4 flex-wrap">
                {/* Example interactive buttons */}
                <button className="px-4 py-2 rounded-xl bg-green-500 text-white hover:bg-green-600">
                  Check Heart Rate ❤️
                </button>
                <button className="px-4 py-2 rounded-xl bg-blue-500 text-white hover:bg-blue-600">
                  Measure Temperature 🌡️
                </button>
                <button className="px-4 py-2 rounded-xl bg-purple-500 text-white hover:bg-purple-600">
                  Diagnose 🩺
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Footer encouragement */}
      <div className="text-center text-gray-600 text-sm mt-8">
        👩‍⚕️ Have fun learning and exploring the hospital!
      </div>
    </main>
  );
};

export default Learn;
